function validate([n, edgeList, queries]) {
  if (!Number.isInteger(n) || n < 2 || n > 100000) return 'n is between 2 and 10^5.';
  if (!Array.isArray(edgeList) || edgeList.length < 1 || edgeList.length > 100000) return 'edgeList needs 1 to 10^5 edges.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 entries.';
  const node = x => Number.isInteger(x) && x >= 0 && x < n;
  const weight = w => Number.isInteger(w) && w >= 1 && w <= 1000000000;
  for (const e of edgeList) {
    if (!Array.isArray(e) || e.length !== 3) return 'Each edge is [u, v, dis].';
    if (!node(e[0]) || !node(e[1])) return 'Edge ends must be nodes 0 to n - 1.';
    if (e[0] === e[1]) return 'An edge must join two different nodes.';
    if (!weight(e[2])) return 'Edge lengths are between 1 and 10^9.';
  }
  for (const t of queries) {
    if (!Array.isArray(t) || t.length !== 3) return 'Each query is [p, q, limit].';
    if (!node(t[0]) || !node(t[1])) return 'Query nodes must be 0 to n - 1.';
    if (t[0] === t[1]) return 'A query must name two different nodes.';
    if (!weight(t[2])) return 'Limits are between 1 and 10^9.';
  }
  return null;
}

