function distanceLimitedPathsExist(n, edgeList, queries) {
  // Answer each query on its own with a breadth-first search over the short enough edges.
  return queries.map(([p, q, limit]) => {
    const reached = new Array(n).fill(false);
    reached[p] = true;
    const stack = [p];
    while (stack.length) {
      const node = stack.pop();
      for (const [u, v, dis] of edgeList) {
        if (dis >= limit) continue;
        if (u === node && !reached[v]) { reached[v] = true; stack.push(v); }
        if (v === node && !reached[u]) { reached[u] = true; stack.push(u); }
      }
    }
    return reached[q];
  });
}

