function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(500, 1500) : int(2, 7);
  const edgeCount = large ? int(1000, 2000) : int(1, 10);
  const queryCount = large ? int(1000, 2000) : int(1, 8);
  const top = large ? (rand() < 0.5 ? 1000 : 1000000000) : int(2, 12);
  const pair = () => {
    const a = int(0, n - 1);
    let b = int(0, n - 2);
    if (b >= a) b++;
    return [a, b];
  };
  const edgeList = Array.from({ length: edgeCount }, () => [...pair(), int(1, top)]);
  const queries = Array.from({ length: queryCount }, () => [...pair(), int(1, Math.min(top + 1, 1000000000))]);
  return [n, edgeList, queries];
}
